	private class RandomSwap : IDisposable
	{
		private UnifiedRandom prev;

		public static RandomSwap Swap(UnifiedRandom r)
		{
			Utils.Swap(ref rand, ref r);
			return new RandomSwap
			{
				prev = r
			};
		}

		public void Dispose()
		{
			rand = prev;
		}
	}

