		}
	}

	public float UIScaleMax
	{
		get
		{
			int realScreenWidth = PlayerInput.RealScreenWidth;
			float val = Math.Min(val2: (float)PlayerInput.RealScreenHeight / 600f, val1: (float)realScreenWidth / 800f);
			return Math.Max(1f, val);
		}
	}

