			dust[j] = new Dust();
			dust[j].dustIndex = j;
		}
		for (int k = 0; k < 401; k++)
		{
			item[k] = new WorldItem();
			item[k].whoAmI = k;
		}
		for (int l = 0; l < maxNPCs + 1; l++)
		{
			npc[l] = new NPC();
			npc[l].whoAmI = l;
		}
		for (int m = 0; m < 256; m++)
		{
			player[m] = new Player();
			player[m].whoAmI = m;
		}
