		}
		for (int num5 = 0; num5 < 20; num5++)
		{
			PopupText.popupText[num5] = new PopupText();
		}
	}

	private static void Initialize_Items()
	{
		for (int i = 0; i < ItemID.Count; i++)
		{
			Item item = new Item();
			item.SetDefaults(i);
			if (item.headSlot > 0)
			{
				Item.headType[item.headSlot] = item.type;
			}
			if (item.bodySlot > 0)
			{
				Item.bodyType[item.bodySlot] = item.type;
			}
			if (item.legSlot > 0)
			{
				Item.legType[item.legSlot] = item.type;
			}
			switch (item.type)
			{
			case 683:
			case 723:
			case 726:
			case 739:
			case 740:
			case 741:
			case 742:
			case 743:
			case 744:
			case 788:
			case 1296:
			case 1308:
			case 1326:
			case 1444:
			case 1445:
			case 1446:
			case 1801:
			case 1930:
			case 1931:
			case 2188:
			case 2750:
			case 3006:
			case 3051:
			case 3209:
			case 3210:
			case 3377:
			case 3476:
			case 3569:
			case 3571:
			case 3787:
			case 3852:
			case 3870:
			case 4062:
			case 5065:
			case 6152:
			case 6153:
			case 6154:
			case 6155:
			case 6173:
				Item.staff[item.type] = true;
				break;
			case 1827:
				Item.claw[item.type] = true;
				break;
			}
		}
	}

