			{
				NPC.totalInvasionPoints = 0f;
				NPC.waveKills = 0f;
				NPC.waveNumber = 0;
			}
		}
		if (snowMoon)
		{
			snowMoon = false;
			if (netMode != 1)
			{
				NPC.totalInvasionPoints = 0f;
				NPC.waveKills = 0f;
				NPC.waveNumber = 0;
			}
		}
	}

