	public static void checkXMas()
	{
		DateTime now = DateTime.Now;
		int day = now.Day;
		int month = now.Month;
		if (day >= 15 && month == 12)
		{
			xMas = true;
		}
		else
		{
			xMas = false;
		}
		if (forceXMasForToday)
		{
			xMas = true;
		}
		if (forceXMasForever)
		{
			xMas = true;
		}
	}

	public static bool isHalloweenDateNow()
	{
		DateTime now = DateTime.Now;
		int day = now.Day;
		int month = now.Month;
		if (day < 10 || month != 10)
		{
			if (day <= 1)
			{
				return month == 11;
			}
			return false;
		}
		return true;
	}

	public static void checkHalloween()
	{
		halloween = false;
		if (isHalloweenDateNow())
		{
			halloween = true;
		}
		if (forceHalloweenForToday)
		{
			halloween = true;
		}
		if (forceHalloweenForever)
		{
			halloween = true;
		}
	}

