	private void UpdateWorld_Projectiles()
	{
		TimeLogger.StartTimestamp fromTimestamp = TimeLogger.Start();
		LockOnHelper.SetUP();
		CurrentFrameFlags.HadAnActiveInteractableProjectile = false;
		PreUpdateAllProjectiles();
		for (int i = 0; i < 1000; i++)
		{
			ProjectileUpdateLoopIndex = i;
			try
			{
				projectile[i].Update(i);
			}
			catch
			{
				if (!ignoreErrors)
				{
					throw;
				}
				projectile[i] = new Projectile();
			}
		}
		ProjectileUpdateLoopIndex = -1;
		PostUpdateAllProjectiles();
		LockOnHelper.SetDOWN();
