	private void UpdateWorld_Items()
	{
		TimeLogger.StartTimestamp fromTimestamp = TimeLogger.Start();
		for (int i = 0; i < 400; i++)
		{
			try
			{
				item[i].UpdateItem(i);
			}
			catch
			{
				if (!ignoreErrors)
				{
					throw;
				}
				item[i] = new WorldItem();
				item[i].whoAmI = i;
			}
		}
		TimeLogger.UpdateItems.AddTime(fromTimestamp);
	}

	private void UpdateWorld_Dust()
