	{
		if (keyState.IsKeyDown((Keys)13) && !keyState.IsKeyDown((Keys)164) && !keyState.IsKeyDown((Keys)165))
		{
			if (chatRelease && !drawingPlayerChat && !editSign && !editChest && !CaptureManager.Instance.Active && !ingameOptionsWindow && ((!gameMenu && !inFancyUI) || menuChat) && !keyState.IsKeyDown((Keys)27))
			{
				SoundEngine.PlaySound(10);
