	private void TryDespawningProjectile_ModifyBeforeKill(Projectile proj, ref bool giveItem)
	{
		if (proj.aiStyle == 16 && !proj.hostile)
		{
			proj.ai[0] = 1000f;
			NetMessage.SendData(27, -1, -1, null, proj.whoAmI);
		}
	}

	private void TryDespawningProjectile_SpecialkillCode(Projectile proj)
	{
		if (proj.type != 250 && proj.type != 251)
		{
			return;
		}
		for (int i = 0; i < 1000; i++)
		{
			Projectile projectile = Main.projectile[i];
			if (projectile.active && projectile.owner == proj.owner && (projectile.type == 250 || projectile.type == 251))
			{
				projectile.Kill();
			}
		}
	}

