	public static bool CanDryadPlayStardewAnimation(Player player, NPC npc)
	{
		Item heldItem = player.HeldItem;
		if (!heldItem.IsAir && heldItem.type == 5275 && npc.ai[0] != 24f)
		{
			return npc.type == 20;
		}
		return false;
	}

