	public static bool LocalPlayerHasPendingInventoryActions()
	{
		if (FakeCursorItem.Item.IsAir)
		{
			return CraftingRequests.HasPendingRequests;
		}
		return true;
	}

	public static void CraftItem_GrantItem(Recipe recipe, Item result, bool quickCraft)
	{
		Invariant.Assert(mouseItem.IsAir || Item.CanStack(mouseItem, result), "CraftItem_GrantItem cannot stack with MouseItem");
		result.stack += mouseItem.stack;
		mouseItem = result;
		if (quickCraft && !mouseItem.IsAir)
		{
			if (CraftingRequests.HasPendingRequests)
			{
				LocalPlayer.GetOrDropItem(mouseItem, GetItemSettings.ReturnItemShowAsNewNoCoinMerge);
				mouseItem = new Item();
			}
			else
			{
				mouseItem = LocalPlayer.GetItem(mouseItem, GetItemSettings.ReturnItemShowAsNewNoCoinMerge);
			}
		}
		CraftingEffects.OnCraftItemGranted(recipe, result, quickCraft);
		HandleWeirdCrafts(recipe, result, quickCraft);
		AchievementsHelper.NotifyItemCraft(recipe);
		AchievementsHelper.NotifyItemPickup(player[myPlayer], recipe.createItem);
	}

	private static void HandleWeirdCrafts(Recipe recipe, Item result, bool quickCraft)
	{
		if (recipe.createItem.type == 6148)
		{
			KillProjectilesOfTypeForLocalPlayer(1093);
		}
		if (recipe.createItem.type == 6149)
		{
			KillProjectilesOfTypeForLocalPlayer(1094);
		}
	}

	private static void KillProjectilesOfTypeForLocalPlayer(short projIdTokill)
	{
		for (int i = 0; i < 1000; i++)
		{
			Projectile projectile = Main.projectile[i];
			if (projectile.active && projectile.owner == myPlayer && projectile.type == projIdTokill)
			{
				projectile.Kill();
			}
		}
	}

