	public static string GetBuffTooltip(Player player, int buffType)
	{
		string text = Lang.GetBuffDescription(buffType);
		switch (buffType)
		{
		case 26:
			if (expertMode)
			{
				text = Language.GetTextValue("BuffDescription.WellFed_Expert");
			}
			break;
		case 206:
			if (expertMode)
			{
				text = Language.GetTextValue("BuffDescription.WellFed2_Expert");
			}
			break;
		case 207:
			if (expertMode)
			{
				text = Language.GetTextValue("BuffDescription.WellFed3_Expert");
			}
			break;
		case 94:
		{
			if (DebugOptions.ManaPotionDelay)
			{
				return Language.GetTextValue("BuffDescription.ManaSickness2");
			}
			int num2 = (int)(player.manaSickReduction * 100f) + 1;
			text = text + num2 + "%";
			break;
		}
		case 396:
		{
			int num = (int)(Math.Ceiling(player.manaHeat * 100f) - 100.0);
			text = text + num + "%";
			break;
		}
		}
		return text;
	}

