		}
		else if (pumpkinMoon)
		{
			int num2 = (new int[16]
			{
				0, 25, 40, 50, 80, 100, 160, 180, 200, 250,
				300, 375, 450, 525, 675, 0
			})[waveNumber];
			NetMessage.SendData(78, toWho, -1, null, (int)NPC.waveKills, num2, 2f, waveNumber);
		}
		else if (DD2Event.Ongoing)
		{
			DD2Event.SyncInvasionProgress(toWho);
