	protected void QuitGame()
	{
		SaveSettings();
		if (!dedServ)
		{
			SocialAPI.Shutdown();
		}
		Assets.TransferCompletedAssets();
		this.Exit();
	}

	private void Main_Exiting(object sender, EventArgs e)
	{
		TryDisposingEverything();
	}

	private static void TryDisposingEverything()
