	public static void CycleFrameSkipMode()
	{
		int frameSkipMode = (int)FrameSkipMode;
		frameSkipMode++;
		if (frameSkipMode < 0 || frameSkipMode > 2)
		{
			frameSkipMode = 0;
		}
		FrameSkipMode = (FrameSkipMode)frameSkipMode;
	}

