	private static float ComputeScAdj(float screenY, float screenHeight)
	{
		float num = (float)(worldSurface * 16.0) / (screenY + screenHeight);
		float num2 = (float)maxTilesY * 0.15f * 16f;
		num2 -= screenY;
		if (num2 < 0f)
		{
			num2 = 0f;
		}
		num2 *= 0.00025f;
		float num3 = num2 * num2;
		num *= 0.45f - num3;
		if (maxTilesY <= 1200)
		{
			return num * -500f;
		}
		if (maxTilesY <= 1800)
		{
			return num * -300f;
		}
		return num * -150f;
	}

