			if (WorldGen.drunkWorldGen)
			{
				if (onlyShimmerOceanWorldsGeneration)
				{
					bgStyle = 6;
				}
				else if (vampireSeed)
				{
					bgStyle = 8;
				}
				else if (WorldGen.notTheBees)
				{
					bgStyle = 3;
				}
				else
				{
					bgStyle = 9;
				}
			}
		}
